from z3 import *

n = 23
min_edges = 44

# Edge variables: e[i][j] for i < j
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = Bool(f"e_{i}_{j}")

# Color variables: c[i][k] = True if vertex i has color k
c = {}
for i in range(n):
    for k in range(3):
        c[(i,k)] = Bool(f"c_{i}_{k}")

s = Solver()

# Each vertex has exactly one color
for i in range(n):
    s.add(Or(c[(i,0)], c[(i,1)], c[(i,2)]))
    for k1 in range(3):
        for k2 in range(k1+1, 3):
            s.add(Or(Not(c[(i,k1)]), Not(c[(i,k2)])))

# Adjacent vertices have different colors
for i in range(n):
    for j in range(i+1, n):
        for k in range(3):
            s.add(Or(Not(e[(i,j)]), Not(c[(i,k)]), Not(c[(j,k)])))

# No triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(Or(Not(e[(i,j)]), Not(e[(j,k)]), Not(e[(i,k)])))

# No 4-cycles
# For each 4-subset, enumerate the 3 possible 4-cycles
from itertools import combinations
for verts in combinations(range(n), 4):
    a, b, c_v, d = verts
    # Cycle 1: a-b-c-d-a
    s.add(Or(Not(e[(a,b)]), Not(e[(b,c_v)]), Not(e[(c_v,d)]), Not(e[(a,d)])))
    # Cycle 2: a-b-d-c-a
    s.add(Or(Not(e[(a,b)]), Not(e[(b,d)]), Not(e[(c_v,d)]), Not(e[(a,c_v)])))
    # Cycle 3: a-c-b-d-a
    s.add(Or(Not(e[(a,c_v)]), Not(e[(b,c_v)]), Not(e[(b,d)]), Not(e[(a,d)])))

# At least 44 edges
edge_vars = [e[(i,j)] for i in range(n) for j in range(i+1, n)]
s.add(PbGe([(ev, 1) for ev in edge_vars], min_edges))

print("Constraints added. Solving...")
result = s.check()
print("Result:", result)

