import random
from itertools import combinations

def has_triangle(edges_set):
    """Check if graph has a triangle"""
    adj = {i: set() for i in range(23)}
    for u, v in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(23):
        for v in adj[u]:
            if v > u:
                for w in adj[u]:
                    if w > v and w in adj[v]:
                        return True
    return False

def has_4cycle(edges_set):
    """Check if graph has a 4-cycle"""
    adj = {i: set() for i in range(23)}
    for u, v in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    for a in range(23):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c != a:
                        for d in adj[c]:
                            if d != b and d != a and d in adj[a]:
                                # Check if it's a proper 4-cycle
                                if len({a, b, c, d}) == 4:
                                    return True
    return False

def is_3colorable(edges_set):
    """Check if graph is 3-colorable using backtracking"""
    adj = {i: set() for i in range(23)}
    for u, v in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * 23

    def backtrack(v):
        if v == 23:
            return True
        for c in range(3):
            valid = True
            for u in adj[v]:
                if colors[u] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

