random.seed(42)

# Start with a random graph and remove bad edges
best_edges = []
best_count = 0

for trial in range(1000):
    # Generate random graph
    possible_edges = list(combinations(range(23), 2))
    random.shuffle(possible_edges)

    edges = []
    edges_set = set()

    for u, v in possible_edges:
        # Try adding this edge
        test_edges = edges_set | {(u, v)}
        if not has_triangle(test_edges) and not has_4cycle(test_edges):
            edges.append((u, v))
            edges_set.add((u, v))

    if len(edges) > best_count:
        best_count = len(edges)
        best_edges = edges[:]
        print(f"Trial {trial}: {len(edges)} edges")

        if len(edges) >= 44:
            print("Found graph with", len(edges), "edges")
